<?php require_once __DIR__.'/config.php';$id=(int)($_GET['id']??0);$thread=null;foreach(data_load('threads.json') as $t)if((int)$t['id']===$id)$thread=$t;if(!$thread){http_response_code(404);exit('Тема не найдена');}$replies=data_load('replies_'.$id.'.json');$likes=data_load('likes_thread_'.$id.'.json');$me=current_user();$title=($thread['title']??'Тема').' — GREFFRLEND';include __DIR__.'/includes/header.php';?>
<article class="card post"><div class="category">ТЕМА</div><h1><?=e($thread['title']??'')?></h1><div class="post-meta"><span><?=e($thread['author']??'')?> · <?=e((string)($thread['created_at']??''))?></span><?php if(!empty($thread['pinned'])):?><span class="pin">📌 Закреплено</span><?php endif;?></div><div class="post-body"><?=nl2br(e((string)($thread['content']??'')))?></div><?php if(!empty($thread['attachments'])):?><div class="attachments"><?php foreach($thread['attachments'] as $a):?><img src="<?=e($a)?>" alt="Вложение"><?php endforeach;?></div><?php endif;?><div class="reactions"><form method="post" action="like.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="type" value="thread"><input type="hidden" name="id" value="<?=$id?>"><button class="reaction">❤️ <?=count($likes)?></button></form><?php if($me&&((int)($thread['author_id']??0)===(int)$me['id']||is_owner($me))):?><form method="post" action="content_action.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="type" value="thread"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="delete"><button class="reaction">Удалить</button></form><?php endif;?><?php if($me&&is_owner($me)):?><form method="post" action="content_action.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="type" value="thread"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="pin"><button class="reaction">📌 <?=!empty($thread['pinned'])?'Открепить':'Закрепить'?></button></form><?php endif;?></div></article>
<h2>Комментарии</h2><?php foreach($replies as $r):$rlikes=data_load('likes_reply_'.(int)$r['id'].'.json');?><article class="card post"><div class="post-meta"><b><?=e($r['author']??'')?></b><span><?=e((string)($r['created_at']??''))?></span></div><div class="post-body"><?=nl2br(e((string)($r['message']??'')))?></div><?php if(!empty($r['attachments'])):?><div class="attachments"><?php foreach($r['attachments'] as $a):?><img src="<?=e($a)?>" alt="Вложение"><?php endforeach;?></div><?php endif;?><div class="reactions"><form method="post" action="like.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="type" value="reply"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="reaction">❤️ <?=count($rlikes)?></button></form><?php if($me&&((int)($r['author_id']??0)===(int)$me['id']||is_owner($me))):?><form method="post" action="content_action.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="type" value="reply"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="reply_id" value="<?=$r['id']?>"><input type="hidden" name="action" value="delete"><button class="reaction">Удалить</button></form><?php endif;?></div></article><?php endforeach;?>
<?php if($me):?><div class="card form"><h2>Ответить</h2><div class="emoji"><?php foreach(['😀','😂','❤️','🔥','👍','👎','🎮','😎','🤔','🎉','💀','🚀'] as $emoji):?><button type="button" onclick="insertEmoji('<?=e($emoji)?>')"><?=e($emoji)?></button><?php endforeach;?></div><form method="post" action="reply.php" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="thread_id" value="<?=$id?>"><textarea name="message" required maxlength="20000"></textarea><label>Фото/GIF (до <?=MAX_ATTACHMENTS?> файлов)</label><input type="file" name="attachments[]" accept="image/jpeg,image/png,image/gif,image/webp" multiple><button class="btn">Отправить</button></form></div><?php else:?><div class="card">Чтобы отвечать, <a href="login.php">войдите</a> или <a href="register.php">зарегистрируйтесь</a>.</div><?php endif;?><?php include __DIR__.'/includes/footer.php'; ?>